<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {api,download,duration,type State,type Worker,type Task} from '../api';import {X,Send,Check,Video,Clock,Download} from 'lucide-vue-next';
const props=defineProps<{state:State;task:Task;workers:Worker[]}>();const emit=defineEmits<{close:[];refresh:[]}>();const error=ref(''),busy=ref(false),text=ref(''),videoUrl=ref(''),history=ref<{at:string;battery:number;distance:number;temperature:number}[]>([]);
const messages=computed(()=>props.state.messages.filter(m=>m.task===props.task.id).sort((a,b)=>a.at.localeCompare(b.at)));const events=computed(()=>props.state.events.filter(e=>e.task===props.task.id).sort((a,b)=>b.at.localeCompare(a.at)));const names=(id:string)=>id==='admin'?'调度中心':props.workers.find(w=>w.username===id)?.displayName||id;
watch(()=>props.task.id,()=>{videoUrl.value=props.task.videoUrl||'';},{immediate:true});
watch(()=>props.state,async()=>{const id=props.task.id;try{const data=await api<typeof history.value>('/tasks/'+id+'/telemetry');if(id===props.task.id)history.value=data;}catch(e){error.value=(e as Error).message;}},{immediate:true});
async function perform(fn:()=>Promise<void>){busy.value=true;try{await fn();error.value='';emit('refresh');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function send(){await perform(async()=>{await api('/tasks/'+props.task.id+'/messages',{text:text.value});text.value='';});}
async function video(){await perform(async()=>{await api('/tasks/'+props.task.id+'/video',{url:videoUrl.value},'PUT');});}
const labels:Record<string,string>={create:'创建任务',approve:'审核通过',dispatch:'下发任务',start:'开始巡检',pause:'暂停巡检',finish:'提交结果',review:'复核归档',instruction:'下发指令',feedback:'现场反馈',ack:'确认告警',message_ack:'确认消息'};
</script>
<template><Teleport to="body"><div class="drawer-backdrop" @click.self="emit('close')"><section class="detail-drawer"><div class="panel-heading"><div><small>巡检任务 / {{task.id}}</small><h2>{{task.name}}</h2></div><button @click="emit('close')" aria-label="关闭任务详情"><X :size="22"/></button></div><div class="drawer-body"><div v-if="error" class="error">{{error}}</div><div class="task-summary"><span>作业人员<strong>{{names(task.worker)}}</strong></span><span>作业区间<strong>{{task.start}} → {{task.end}}</strong></span><span>累计巡检<strong>{{duration(task.workedSeconds+(task.resumedAt?(Date.now()-Date.parse(task.resumedAt))/1000:0))}}</strong></span></div><div class="task-dates"><p>开始：{{task.startedAt?new Date(task.startedAt).toLocaleString():'尚未开始'}}</p><p>完成：{{task.finishedAt?new Date(task.finishedAt).toLocaleString():'尚未完成'}}</p></div><div class="video-preview"><video v-if="task.videoUrl" :src="task.videoUrl" controls @error="error='视频连接失败，请检查地址和编码格式'"/><div v-else><Video :size="32"/><span>尚未连接摄像头</span></div></div><div class="inline-form"><input v-model="videoUrl" placeholder="摄像头网关视频地址"/><button class="outline" @click="video" :disabled="busy">保存视频</button></div><h3>巡检结果</h3><p class="result-note">{{task.note||'暂无现场记录'}}</p><h3>指令与现场反馈</h3><div class="conversation"><article v-for="m in messages" :key="m.id" :class="{outgoing:m.sender==='admin'}"><div><strong>{{names(m.sender)}}</strong><small>{{new Date(m.at).toLocaleString()}}</small></div><p>{{m.text}}</p><small>{{m.acknowledged?'对方已确认':'等待确认'}}</small><button v-if="m.sender!=='admin'&&!m.acknowledged" class="text-btn" @click="perform(async()=>{await api('/messages/'+m.id+'/ack',{});})">确认收到</button></article><p v-if="!messages.length" class="empty">暂无指令与反馈</p></div><div class="inline-form"><input v-model="text" maxlength="500" placeholder="输入现场指令或补充说明" @keyup.enter="()=>{if(text.trim())send();}"/><button class="primary" @click="send" :disabled="busy||!text.trim()"><Send :size="16"/>发送</button></div><h3>作业时间线</h3><div class="event-log"><article v-for="e in events" :key="e.id"><span class="dot"/><div><strong>{{labels[e.action]||e.action}}</strong><small>{{names(e.actor)}} · {{new Date(e.at).toLocaleString()}}</small><p>{{e.text}}</p></div></article></div><h3>设备遥测记录 <button class="text-btn" @click="download(task.id+'-遥测.json',history)"><Download :size="15"/>导出</button></h3><p v-if="!history.length" class="hint">暂无设备上报记录</p><table v-else><thead><tr><th>时间</th><th>电量</th><th>里程</th><th>温度</th></tr></thead><tbody><tr v-for="(r,i) in history.slice(0,20)" :key="i"><td>{{new Date(r.at).toLocaleTimeString()}}</td><td>{{r.battery}}%</td><td>{{r.distance}}m</td><td>{{r.temperature}}℃</td></tr></tbody></table></div></section></div></Teleport></template>
